ValidationRule.errorConditionFormula:
AND( ISCHANGED(Process_Status__c ) , ISPICKVAL(Process_Status__c , 'Cancelled'), ISBLANK(Cancellation_Reason__c ), $Profile.Name = 'System Administrator', $Profile.Name = 'Qantas System Administrator', $Profile.Name = 'Qantas System Admin - Freight', $Profile.Name = 'Qantas System Admin - QCC', $Profile.Name = 'Qantas System Admin - SND', OR(
/* EFT Record Type check */ AND(RecordType.DeveloperName = 'EFT_Recovery', OR(ISPICKVAL(PRIORVALUE(Process_Status__c ), 'Submitted to Finance'), ISPICKVAL(PRIORVALUE(Process_Status__c ), 'Findel Approved'), ISPICKVAL(PRIORVALUE(Process_Status__c ), 'Payment Ready'))),
/* CC Record Type check */ AND(RecordType.DeveloperName = 'Credit_Card_Recovery', ISPICKVAL(PRIORVALUE(Process_Status__c ), 'Submitted to Finance') ),
/* TV Record Type check */ AND(RecordType.DeveloperName = 'Travel_Voucher_Recovery', ISPICKVAL(PRIORVALUE(Process_Status__c ), 'Submitted for Voucher Issuance')) ) )
